"""Validate auth.py end-to-end on a scratch database.

Also reports whether any existing .db files in this workspace have a
compatible ``users`` table. Existing databases are opened read-only and are
never modified by this script.
"""

from __future__ import annotations

import os
import sqlite3
import sys
import tempfile

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)

import auth  # noqa: E402

REQUIRED_COLUMNS = {"username", "email", "password_hash", "created_date"}


def report_workspace_dbs() -> None:
    """Print a compatibility report for existing .db files (read-only)."""
    db_files = [
        entry
        for entry in sorted(os.listdir(HERE))
        if entry.endswith(".db") and os.path.isfile(os.path.join(HERE, entry))
    ]
    if not db_files:
        print(
            "Workspace .db files: none "
            f"(auth.py defaults to {os.path.basename(auth.DEFAULT_DB_PATH)} on init)"
        )
        return
    for entry in db_files:
        path = os.path.join(HERE, entry)
        try:
            with sqlite3.connect(f"file:{path}?mode=ro", uri=True) as conn:
                tables = {
                    row[0]
                    for row in conn.execute(
                        "SELECT name FROM sqlite_master WHERE type = 'table'"
                    )
                }
                if "users" not in tables:
                    print(
                        f"Workspace .db files: {entry} has no 'users' table "
                        "(run `python auth.py init`)"
                    )
                    continue
                cols = {row[1] for row in conn.execute("PRAGMA table_info(users)")}
                missing = REQUIRED_COLUMNS - cols
                if missing:
                    print(
                        f"Workspace .db files: {entry} 'users' table is missing "
                        f"columns {sorted(missing)}"
                    )
                else:
                    print(
                        f"Workspace .db files: {entry} 'users' table compatible "
                        f"(columns: {sorted(cols)})"
                    )
        except sqlite3.DatabaseError as exc:
            print(f"Workspace .db files: {entry} ERROR: {exc}")


def main() -> int:
    report_workspace_dbs()

    with tempfile.TemporaryDirectory() as tmp:
        db_path = os.path.join(tmp, "scratch.db")
        auth.init_db(db_path)

        created = auth.register_user(db_path, "alice", "alice@example.com", "s3cret!")
        print(f"Registered alice at {created}")

        assert auth.login_user(db_path, "alice", "s3cret!") is True
        assert auth.login_user(db_path, "alice", "wrong-password") is False
        assert auth.login_user(db_path, "unknown", "s3cret!") is False

        for label, kwargs in [
            (
                "duplicate username",
                {"username": "alice", "email": "new@example.com", "password": "x"},
            ),
            (
                "duplicate email",
                {"username": "bob", "email": "alice@example.com", "password": "x"},
            ),
            (
                "bad email",
                {"username": "bob", "email": "not-an-email", "password": "x"},
            ),
        ]:
            try:
                auth.register_user(db_path, **kwargs)
            except ValueError as exc:
                print(f"{label} rejected: {exc}")
            else:
                raise AssertionError(f"{label} was not rejected")

        with sqlite3.connect(db_path) as conn:
            stored = conn.execute(
                "SELECT password_hash FROM users WHERE username = ?", ("alice",)
            ).fetchone()[0]
            assert stored.startswith("pbkdf2_sha256$"), "unexpected hash format"
            assert stored != "s3cret!", "raw password stored in database"

        print("All auth checks passed against a scratch database.")
    return 0


if __name__ == "__main__":
    sys.exit(main())

